pass:
    li t0, STDOUT
    li t1, 0xff
    sb t1, 0(t0)
1:  j 1b

fail:                           // print "FAIL <check#>" (hex), then signal failure
    li t0, STDOUT
    la t1, fail_msg
2:  lbu t2, 0(t1)
    beqz t2, 3f
    sb t2, 0(t0)
    addi t1, t1, 1
    j 2b
3:  li t1, 28
4:  srl t2, t6, t1
    andi t2, t2, 15
    addi t2, t2, '0'
    li t3, '9'
    ble t2, t3, 5f
    addi t2, t2, 'a'-'0'-10
5:  sb t2, 0(t0)
    addi t1, t1, -4
    bgez t1, 4b
    li t2, 10
    sb t2, 0(t0)
    li t1, 1
    sb t1, 0(t0)
6:  j 6b

